import { DEFAULT_SYSTEM_SCHEMAS } from "./constants.js";
import { filterByList } from "./helpers.js";
import { TABLE_RELATIONSHIPS_SQL } from "./sql/table_relationships.sql.js";
import { VIEWS_KEY_DEPENDENCIES_SQL } from "./sql/views_key_dependencies.sql.js";
// src/vendor/postgres-meta/lib/PostgresMetaRelationships.ts
var PostgresMetaRelationships = class {
	constructor(query) {
		this.query = query;
	}
	async list({ includeSystemSchemas = false, includedSchemas, excludedSchemas } = {}) {
		const schemaFilter = filterByList(includedSchemas, excludedSchemas, !includeSystemSchemas ? DEFAULT_SYSTEM_SCHEMAS : void 0);
		let allTableM2oAndO2oRelationships;
		{
			const sql = TABLE_RELATIONSHIPS_SQL({ schemaFilter });
			const { data, error } = await this.query(sql);
			if (error) return {
				data: null,
				error
			};
			allTableM2oAndO2oRelationships = data;
		}
		let allViewM2oAndO2oRelationships;
		{
			const viewsKeyDependenciesSql = VIEWS_KEY_DEPENDENCIES_SQL({ schemaFilter });
			const { data: viewsKeyDependencies, error } = await this.query(viewsKeyDependenciesSql);
			if (error) return {
				data: null,
				error
			};
			allViewM2oAndO2oRelationships = allTableM2oAndO2oRelationships.flatMap((r) => {
				const expandKeyDepCols = (colDeps) => {
					const tableColumns = colDeps.map(({ table_column }) => table_column);
					const cartesianProduct = (allEntries) => {
						return allEntries.reduce((results, entries) => results.map((result) => entries.map((entry) => result.concat(entry))).reduce((subResults, result) => subResults.concat(result), []), [[]]);
					};
					return cartesianProduct(colDeps.map((cd) => cd.view_columns)).map((viewColumns) => ({
						tableColumns,
						viewColumns
					}));
				};
				const viewToTableKeyDeps = viewsKeyDependencies.filter((vkd) => vkd.table_schema === r.schema && vkd.table_name === r.relation && vkd.constraint_name === r.foreign_key_name && vkd.constraint_type === "f");
				const tableToViewKeyDeps = viewsKeyDependencies.filter((vkd) => vkd.table_schema === r.referenced_schema && vkd.table_name === r.referenced_relation && vkd.constraint_name === r.foreign_key_name && vkd.constraint_type === "f_ref");
				const viewToTableRelationships = viewToTableKeyDeps.flatMap((vtkd) => expandKeyDepCols(vtkd.column_dependencies).map(({ viewColumns }) => ({
					foreign_key_name: r.foreign_key_name,
					schema: vtkd.view_schema,
					relation: vtkd.view_name,
					columns: viewColumns,
					is_one_to_one: r.is_one_to_one,
					referenced_schema: r.referenced_schema,
					referenced_relation: r.referenced_relation,
					referenced_columns: r.referenced_columns
				})));
				const tableToViewRelationships = tableToViewKeyDeps.flatMap((tvkd) => expandKeyDepCols(tvkd.column_dependencies).map(({ viewColumns }) => ({
					foreign_key_name: r.foreign_key_name,
					schema: r.schema,
					relation: r.relation,
					columns: r.columns,
					is_one_to_one: r.is_one_to_one,
					referenced_schema: tvkd.view_schema,
					referenced_relation: tvkd.view_name,
					referenced_columns: viewColumns
				})));
				const viewToViewRelationships = viewToTableKeyDeps.flatMap((vtkd) => expandKeyDepCols(vtkd.column_dependencies).flatMap(({ viewColumns }) => tableToViewKeyDeps.flatMap((tvkd) => expandKeyDepCols(tvkd.column_dependencies).map(({ viewColumns: referencedViewColumns }) => ({
					foreign_key_name: r.foreign_key_name,
					schema: vtkd.view_schema,
					relation: vtkd.view_name,
					columns: viewColumns,
					is_one_to_one: r.is_one_to_one,
					referenced_schema: tvkd.view_schema,
					referenced_relation: tvkd.view_name,
					referenced_columns: referencedViewColumns
				})))));
				return [
					...viewToTableRelationships,
					...tableToViewRelationships,
					...viewToViewRelationships
				];
			});
		}
		return {
			data: allTableM2oAndO2oRelationships.concat(allViewM2oAndO2oRelationships),
			error: null
		};
	}
};
export { PostgresMetaRelationships as default };
